create or replace function public.ensure_kintex_household() returns uuid language plpgsql security invoker set search_path = '' as $$ declare current_user_id uuid := auth.uid(); household uuid; begin if current_user_id is null then raise exception 'not_authenticated'; end if; insert into public.profiles (id) values (current_user_id) on conflict (id) do nothing; select id into household from public.households where owner_id = current_user_id order by created_at, id limit 1; if household is null then insert into public.households (owner_id, name, country) values (current_user_id, 'KintexBG', 'DE') returning id into household; end if; return household; end; $$; revoke all on function public.ensure_kintex_household() from public, anon; grant execute on function public.ensure_kintex_household() to authenticated
